// Helper function to create a first admin user
export async function createFirstAdminIfNeeded(email: string, password: string, name: string) {
  try {
    // Check if there are any users first
    const { count, error: countError } = await supabase
      .from('profiles')
      .select('*', { count: 'exact', head: true });
    
    if (countError) {
      console.error('Error checking for users:', countError);
      return;
    }
    
    // If no users exist, create the first admin
    if (count === 0) {
      const { data, error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: {
            name,
          },
        }
      });
      
      if (error) {
        console.error('Error creating first admin:', error);
        return;
      }
      
      // Update the user's role to admin
      if (data.user) {
        await supabase
          .from('profiles')
          .update({ role: 'admin' })
          .eq('id', data.user.id);
      }
      
      console.log('First admin user created successfully!');
    }
  } catch (error) {
    console.error('Error in createFirstAdminIfNeeded:', error);
  }
}
